using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedNinetyFiveHundredCents()
    {
        // Bronze customer is charged the reduced total
        Assert.Equal(9500, ChargedFor(10000, LoyaltyTier.Bronze));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedNineThousandCents()
    {
        // Silver customer is charged the reduced total
        Assert.Equal(9000, ChargedFor(10000, LoyaltyTier.Silver));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedEightyFiveHundredCents()
    {
        // Gold customer is charged the reduced total
        Assert.Equal(8500, ChargedFor(10000, LoyaltyTier.Gold));
    }

    [Fact]
    public void S4_BronzeCustomerSmallBasketIsChargedSevenCents()
    {
        // Bronze customer with a tiny basket is charged a whole-cent total
        Assert.Equal(7, ChargedFor(7, LoyaltyTier.Bronze));
    }
}
